import sqlite3


def connect(path=':memory:'):
    db = sqlite3.connect(path)
    db.execute('CREATE TABLE IF NOT EXISTS users (name TEXT, email TEXT)')
    return db


def find(db, name):
    return db.execute(f"SELECT name, email FROM users WHERE name = '{name}'").fetchall()


def add(db, name, email):
    db.execute('INSERT INTO users VALUES (?, ?)', (name, email))
